class Flaky:
    def __init__(self, fails):
        self.fails = fails
        self.calls = 0
    def put(self, p):
        self.calls += 1
        if self.calls <= self.fails:
            raise ConnectionError('down')

q = Flaky(3)
attempts = enqueue_with_retry(q, {'job': 1})
assert attempts == 4 and q.calls == 4
print('ok')

class Always:
    def __init__(self):
        self.calls = 0
    def put(self, p):
        self.calls += 1
        raise ConnectionError('down')

q = Always()
try:
    enqueue_with_retry(q, 'x', max_attempts=3)
except RuntimeError as e:
    assert 'exhausted' in str(e) and q.calls == 3
else:
    raise AssertionError('must raise after exhausting')
print('ok')
